#!/usr/bin/env python3
"""
Save richbourse OHLCV data extracted via WebFetch.
This script processes the raw data and saves it to CSV for merging.
"""
import csv
import json
import os
from datetime import datetime

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
DATA_DIR = os.path.join(BASE_DIR, "brvm_data")
OUT_FILE = os.path.join(DATA_DIR, "richbourse_ohlcv.csv")

# Data extracted from WebFetch of richbourse.com
# Format: {ticker: {"ohlc": [[ts,o,h,l,c],...], "volume": [[ts,v],...]}}
RICHBOURSE_DATA = {}

def add_ticker_data(ticker, ohlc_list, volume_list):
    """Add a ticker's OHLCV data."""
    vol_map = {v[0]: v[1] for v in volume_list}
    rows = []
    for entry in ohlc_list:
        ts = entry[0]
        dt = datetime.utcfromtimestamp(ts / 1000)
        rows.append({
            'Symbol': ticker,
            'Date': dt.strftime('%Y-%m-%d'),
            'Open': entry[1],
            'High': entry[2],
            'Low': entry[3],
            'Close': entry[4],
            'Volume': vol_map.get(ts, 0)
        })
    RICHBOURSE_DATA[ticker] = rows
    return len(rows)


