def main():
    print("Saving RichBourse OHLCV data...")
    
    n1 = add_ticker_data("SNTS", snts_ohlc, snts_vol)
    print(f"  SNTS: {n1} rows")
    
    n2 = add_ticker_data("ECOC", ecoc_ohlc, ecoc_vol)
    print(f"  ECOC: {n2} rows")
    
    n3 = add_ticker_data("ORAC", orac_ohlc, orac_vol)
    print(f"  ORAC: {n3} rows")
    
    # Write CSV
    all_rows = []
    for ticker, rows in RICHBOURSE_DATA.items():
        all_rows.extend(rows)
    
    all_rows.sort(key=lambda x: (x['Symbol'], x['Date']))
    
    with open(OUT_FILE, 'w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(f, fieldnames=['Symbol', 'Date', 'Open', 'High', 'Low', 'Close', 'Volume'])
        writer.writeheader()
        writer.writerows(all_rows)
    
    print(f"\nSaved {len(all_rows)} rows to {OUT_FILE}")
    print("Now run consolidate_data.py to merge with sikafinance data!")


if __name__ == "__main__":
    main()
